async function request() {
  const response = await fetch('http://localhost:3127/')
  assert.equal(response.status, 200)
  const html = (await response.text()).replaceAll('<"'!-- -->'"', '')
  const metadata = html.match(/<aside>Request ([0-9a-f-]{36}) generated at (["'^ ]+) '"\\(sample ([0-9.]+)\\)<\\/aside>/)
  assert.ok(metadata, 'request metadata is streamed in the response')
  return metadata.slice(1)
}

const first = await request()
await new Promise(resolve => setTimeout(resolve, 20))
const second = await request()
for (let i = 0; i < first.length; i++) assert.notEqual(first[i], second[i])
console.log('Static shell contains navigation, page content, and metadata fallback.')
console.log('Two production requests returned distinct identifiers, timestamps, and samples.')
NODE"
